<template>
  <section class="supply-sources">
    <h3>{{ governance?'全院库存原件审核与审计':'医院单SKU原始库存资料' }}</h3>
    <p>请求量、毛实发量、确认实耗量分别登记。这里保留未知、缺项和原计数单位；不自动换算，不从当前库存反推历史，不直接发药、采购或调整库存。</p>
    <el-alert v-if="!allowed" type="info" :closable="false" :title="governance?'此治理入口仅限当前超级管理员。':'当前账户没有此原件登记范围权限。'" />
    <template v-else>
      <el-alert v-if="error" type="error" :title="error" :closable="false" />
      <div class="toolbar">
        <el-select :model-value="localKind" aria-label="真实库存品种类型" placeholder="明确选择品种类型" :disabled="!!itemKind" @update:model-value="changeKind"><el-option value="pharmaceutical" label="实际药品" /><el-option value="consumable" label="实际耗材" /></el-select>
        <template v-if="localKind&&!localId"><el-input v-model="keyword" aria-label="真实品种检索文字" placeholder="按实际目录检索" /><el-button @click="searchCatalog">查询实际品种</el-button><el-select :model-value="undefined" aria-label="真实库存品种" placeholder="明确选择实际SKU" @update:model-value="selectItem"><el-option v-for="item in catalog" :key="item.item_id" :value="item.item_id" :label="item.name+' · #'+item.item_id" /></el-select>
          <el-pagination v-if="catalogTotal>20" v-model:current-page="catalogPage" :page-size="20" :total="catalogTotal" layout="prev,pager,next" @current-change="()=>searchCatalog(false)" />
        </template>
        <p v-if="localId">实际{{ localKind==='pharmaceutical'?'药品':'耗材' }}：{{ selectedName||'#'+localId }} · #{{ localId }} · hospital_inventory <el-button v-if="!itemId" @click="selectItem(null)">重新选择品种</el-button></p>
      </div>
      <div class="toolbar"><el-select v-model="recordKind" aria-label="库存原件种类"><el-option value="unit" label="原计数单位定义" /><el-option value="daily" label="原独立日数量" /></el-select><el-button :loading="loading" @click="reload">刷新原件目录</el-button><el-button v-if="localId&&options?.can_record" :disabled="loading||saving" @click="openCreate">登记{{ recordKind==='unit'?'原计数单位':'原独立日数量' }}</el-button></div>
      <p v-if="!governance&&!localId">先明确选择一个真实品种。未选择时不自动使用目录第一项。</p>
      <el-table v-loading="loading" :data="rows" row-key="source_record_id" empty-text="当前范围暂无已登记原件；不表示数量为零">
        <el-table-column prop="item_kind" label="实际品种类型" /><el-table-column prop="item_id" label="实际SKU标识" /><el-table-column label="原口径"><template #default="{row}">{{ supplySourceTargets[row.target]||'计数单位定义' }}</template></el-table-column>
        <el-table-column label="治理状态"><template #default="{row}">{{ supplySourceStates[row.status] }}</template></el-table-column><el-table-column prop="date" label="原业务日期" /><el-table-column prop="professional_status" label="原专业确认" /><el-table-column prop="recorded_at" label="服务器登记UTC6" width="245" /><el-table-column label="操作" width="135"><template #default="{row}"><el-button @click="inspect(row)">核对原件</el-button></template></el-table-column>
      </el-table>
      <el-pagination v-if="total>20" v-model:current-page="page" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="()=>loadList()" />
    </template>
    <el-dialog :model-value="creating" width="min(1050px,95vw)" :title="'登记'+(recordKind==='unit'?'原计数单位定义':'原独立日数量')" destroy-on-close @update:model-value="value=>{if(!value)closeCreate()}">
      <SupplySourceEditor v-if="creating&&form" v-model="form" :kind="recordKind" :item-kind="localKind" :units="units" :selected-unit="selectedUnit" :can-confirm-professional="options?.can_confirm_professional===true" :professional-signer-user-id="options?.professional_signer_user_id??null" @unit-change="chooseUnit" />
      <el-alert v-if="createError" type="error" :title="createError" :closable="false" />
      <template #footer><el-button @click="closeCreate">关闭登记</el-button><el-button type="primary" :disabled="!validForm||unitLoading" :loading="saving" @click="save">保存待审核原件</el-button></template>
    </el-dialog>
    <el-dialog :model-value="!!detail" width="min(1100px,95vw)" title="库存来源原件核对" destroy-on-close @update:model-value="value=>{if(!value)closeDetail()}">
      <template v-if="detail">
        <p>{{ supplySourceStates[detail.status] }} · {{ detail.source_record_id }} · {{ detail.item_kind }} #{{ detail.item_id }}</p>
        <p>原观察UTC6：{{ detail.observed_at??'本单位定义无观察时刻' }}；服务器登记UTC6：{{ detail.recorded_at }}；审核UTC6：{{ detail.reviewed_at??'尚未审核' }}</p>
        <p>原专业确认：{{ detail.professional_status }}；原签署账户：{{ detail.signer_user_id??'未知' }}。治理发布不表示运营验证或执照验证。</p>
        <p v-if="detail.payload?.quantity">原数量：{{ detail.payload.quantity.value===null?'null · '+detail.payload.quantity.absent_reason:detail.payload.quantity.value }}；原单位：{{ detail.payload.original_unit_text??'null · 未知' }}；原供应约束：{{ detail.payload.stock_constraint }}</p>
        <p v-if="detail.payload&&detail.record_kind==='unit'">原计数单位：{{ detail.payload.original_unit_text }}</p>
        <el-alert v-if="!detail.eligible" type="info" :closable="false" :title="detail.payload===null?'当前来源已失效或终止，普通入口已隐去原文。':'当前原件只供草稿审核或冻结审计；不能据此声明完整可用。'" />
        <p>完整原件SHA：{{ detail.content_hash }}</p><p>当前治理SHA：{{ detail.governance_hash }}</p>
        <el-button @click="()=>loadList()">重新核对当前来源目录</el-button>
        <el-button v-if="detail.payload" @click="showOriginal=!showOriginal">{{ showOriginal?'收起院内完整原件':'展开院内完整原件' }}</el-button>
        <pre v-if="showOriginal&&detail.payload" aria-label="库存院内完整原件">{{ JSON.stringify(detail,null,2) }}</pre>
        <template v-if="detail.can_review||detail.can_revoke"><el-form-item label="本次审核或撤销依据"><el-input v-model="basis" type="textarea" aria-label="本次审核或撤销依据" placeholder="至少20个非空白字符；撤销最多1000个Unicode字符/4000UTF-8字节" /></el-form-item>
          <el-button v-if="detail.can_review" :disabled="!supplySourceBasis(basis)||saving" @click="govern('publish')">审核并发布原件</el-button><el-button v-if="detail.can_review" :disabled="!supplySourceBasis(basis)||saving" @click="govern('reject')">审核拒绝原件</el-button><el-button v-if="detail.can_revoke" :disabled="!supplySourceBasis(basis,1000)||saving" type="danger" @click="govern('revoke')">撤销本条原件</el-button>
        </template>
      </template>
    </el-dialog>
  </section>
</template>

<script setup>
import {computed,onActivated,onDeactivated,onUnmounted,ref,watch} from 'vue';
import {useStore} from 'vuex';
import SupplySourceEditor from './SupplySourceEditor.vue';
import {supportCanonical,supportHash} from '@/api/inpatientSupport';
import {createSupplySource,getAdminSupplySource,getAdminSupplySources,getSupplySource,getSupplySourceOptions,getSupplySources,reviewSupplySource,revokeSupplySource,supplySourceBasis,supplySourceMetadataValid,supplySourcePositive,supplySourceRequestValid,supplySourceStates,supplySourceTargets,verifySupplySourceTransition,verifySupplySourceWrapper} from '@/api/ai/supplySources';
const props=defineProps({governance:Boolean,itemKind:{type:String,default:null},itemId:{type:Number,default:null},active:{type:Boolean,default:true}}),emit=defineEmits(['source-changed','invalidate','scope-change']),store=useStore();
const localKind=ref(props.itemKind),localId=ref(props.itemId),recordKind=ref('daily'),keyword=ref(''),catalog=ref([]),catalogPage=ref(1),catalogTotal=ref(0),selectedName=ref(''),page=ref(1),rows=ref([]),total=ref(0),options=ref(null),loading=ref(false),saving=ref(false),error=ref(''),detail=ref(null),showOriginal=ref(false),basis=ref(''),creating=ref(false),form=ref(null),units=ref([]),selectedUnit=ref(null),unitLoading=ref(false),createError=ref('');
const session=computed(()=>JSON.stringify([store.state.user?.accessToken,store.state.user?.username,store.state.user?.permissions])),roles=computed(()=>store.state.user?.permissions||[]),allowed=computed(()=>!!store.state.user?.accessToken&&(props.governance?roles.value.includes('super_admin'):roles.value.some(r=>['admin','director','pharmacist','super_admin'].includes(r)))),scope=computed(()=>JSON.stringify([session.value,props.active,props.governance,localKind.value,localId.value,recordKind.value]));
let epoch=0,detailEpoch=0,unitEpoch=0,live=true,destroyed=false,initialized=false;
const current=t=>t===epoch&&live&&!destroyed&&props.active&&allowed.value,clone=v=>JSON.parse(JSON.stringify(v));
const validForm=computed(()=>creating.value&&!!form.value&&supplySourceRequestValid(recordKind.value==='unit'?'UnitCreate':'SourceCreate',form.value));
function clear(notify=true){epoch++;detailEpoch++;unitEpoch++;rows.value=[];total.value=0;detail.value=null;showOriginal.value=false;basis.value='';creating.value=false;form.value=null;units.value=[];selectedUnit.value=null;options.value=null;catalog.value=[];catalogTotal.value=0;selectedName.value='';loading.value=saving.value=unitLoading.value=false;error.value=createError.value='';if(notify)emit('invalidate');}
function unavailable(message='当前身份、原件或范围已变化，旧原文与登记内容已清除。'){clear();error.value=message;}
function optionsValid(v){return v&&Array.isArray(v.items)&&v.items.length<=20&&Number.isSafeInteger(v.total)&&v.total>=0&&v.page===catalogPage.value&&v.page_size===20&&v.scope==='hospital_inventory'&&typeof v.can_record==='boolean'&&typeof v.can_review==='boolean'&&typeof v.can_confirm_professional==='boolean'&&(v.can_confirm_professional?supplySourcePositive(v.professional_signer_user_id):v.professional_signer_user_id===null)&&v.items.every(x=>['pharmaceutical','consumable'].includes(x.item_kind)&&supplySourcePositive(x.item_id)&&x.scope==='hospital_inventory'&&x.status===0&&(x.name===null||typeof x.name==='string')&&supportHash(x.identity_hash)&&(!localKind.value||x.item_kind===localKind.value)&&(!localId.value||x.item_id===localId.value))&&new Set(v.items.map(x=>x.item_id)).size===v.items.length;}
async function boot(){const t=epoch;if(!current(t))return;loading.value=true;try{const params={page:catalogPage.value,page_size:20};if(localKind.value)params.item_kind=localKind.value;if(localId.value)params.item_id=localId.value;if(keyword.value)params.keyword=keyword.value;const data=(await getSupplySourceOptions(params)).data;if(!current(t))return;if(!optionsValid(data))throw new Error('实际SKU目录或当前药师身份字段无法核对');options.value=clone(data);catalog.value=clone(data.items);catalogTotal.value=data.total;selectedName.value=data.items.find(x=>x.item_id===localId.value)?.name||'';await loadList(t);}catch(e){if(current(t))unavailable(e?.response?.status===403?'当前账户不能读取原库存范围，旧资料已清除。':e.message||'实际SKU目录无法读取');}finally{if(current(t))loading.value=false;}}
async function loadList(ticket=epoch){const t=ticket;if(!current(t))return;if(!props.governance&&!localId.value){rows.value=[];total.value=0;return;}loading.value=true;try{const params={page:page.value,page_size:20};if(localId.value){params.item_kind=localKind.value;params.item_id=localId.value;}const data=(await (props.governance?getAdminSupplySources({...params,record_kind:recordKind.value}):getSupplySources(recordKind.value,params))).data;if(!current(t))return;if(!data||!Array.isArray(data.items)||!Number.isSafeInteger(data.total)||data.total<0||data.page!==page.value||data.page_size!==20||data.detail_required!==true||data.items.length>20||data.items.some(v=>!supplySourceMetadataValid(v,{kind:recordKind.value,itemKind:localId.value?localKind.value:null,itemId:localId.value})||['payload','parent_binding','review_basis_note','revoke_reason'].some(k=>Object.hasOwn(v,k)))||new Set(data.items.map(v=>v.source_record_id)).size!==data.items.length)throw new Error('原件目录类型、范围或完整分页无法核对');rows.value=clone(data.items);total.value=data.total;}catch(e){if(current(t))unavailable(e.message||'当前原件目录无法读取');}finally{if(current(t))loading.value=false;}}
function reload(){clear();page.value=1;boot();}
function searchCatalog(resetPage=true){if(!localKind.value)return;if(resetPage)catalogPage.value=1;epoch++;detailEpoch++;unitEpoch++;creating.value=false;form.value=null;detail.value=null;showOriginal.value=false;rows.value=[];emit('invalidate');boot();}
function changeKind(kind){if(!['pharmaceutical','consumable'].includes(kind))return;localId.value=null;localKind.value=kind;emit('scope-change',{item_kind:kind,item_id:null,scope:'hospital_inventory'});}
function selectItem(id){if(id!==null&&!catalog.value.some(x=>x.item_id===id))return;localId.value=id;emit('scope-change',{item_kind:localKind.value,item_id:id,scope:'hospital_inventory'});}
async function inspect(meta){const t=epoch,d=++detailEpoch;detail.value=null;showOriginal.value=false;basis.value='';try{const row=(await (props.governance?getAdminSupplySource(meta.source_record_id,meta.record_kind):getSupplySource(meta.record_kind,meta.source_record_id,{audit_only:false}))).data;if(!current(t)||d!==detailEpoch)return;if(!await verifySupplySourceWrapper(row,{kind:meta.record_kind,itemKind:meta.item_kind,itemId:meta.item_id,auditOnly:props.governance})||row.content_hash!==meta.content_hash||row.governance_hash!==meta.governance_hash)throw new Error('来源全文与所选原件目录或当前治理版本不一致');if(current(t)&&d===detailEpoch)detail.value=clone(row);}catch(e){if(current(t)&&d===detailEpoch)unavailable(e.message||'当前来源全文不可读取');}}
function closeDetail(){detailEpoch++;detail.value=null;showOriginal.value=false;basis.value='';}
async function loadUnits(t){const found=[];let expected=null;for(let p=1;p<=41;p++){const data=(await getSupplySources('unit',{item_kind:localKind.value,item_id:localId.value,page:p,page_size:100})).data;if(!current(t)||!creating.value)return;if(!data||!Array.isArray(data.items)||!Number.isSafeInteger(data.total)||data.total<0||data.total>4096||expected!==null&&expected!==data.total||data.page!==p||data.page_size!==100||data.items.some(v=>!supplySourceMetadataValid(v,{kind:'unit',itemKind:localKind.value,itemId:localId.value})))throw new Error('单位原件完整候选集合已变化或超限');expected=data.total;found.push(...data.items);if(found.length===expected){if(new Set(found.map(v=>v.source_record_id)).size!==found.length)throw new Error('单位原件集合有重复');units.value=clone(found.filter(v=>v.status==='published'&&v.eligible));return;}if(!data.items.length||found.length>expected)break;}throw new Error('单位候选未完整读取，未使用截断名单');}
async function openCreate(){if(!localId.value||!options.value?.can_record)return;epoch++;const t=epoch;creating.value=true;form.value={item_kind:localKind.value,item_id:localId.value,scope:'hospital_inventory',payload:recordKind.value==='daily'?{kind:'daily_quantity'}:{}};createError.value='';selectedUnit.value=null;units.value=[];if(recordKind.value==='daily'){unitLoading.value=true;try{await loadUnits(t);}catch(e){if(current(t)&&creating.value)unavailable(e.message);}finally{if(current(t))unitLoading.value=false;}}}
function closeCreate(){if(!creating.value&&!form.value)return;epoch++;unitEpoch++;creating.value=false;form.value=null;units.value=[];selectedUnit.value=null;saving.value=unitLoading.value=false;createError.value='';}
async function chooseUnit(id){const t=epoch,u=++unitEpoch;if(!creating.value||!form.value)return;selectedUnit.value=null;form.value={...form.value,unit_definition_id:undefined,expected_unit_content_hash:undefined,expected_unit_governance_hash:undefined};if(id==='__none__'){form.value={...form.value,unit_definition_id:null,expected_unit_content_hash:null,expected_unit_governance_hash:null};return;}const meta=units.value.find(v=>v.source_record_id===id);if(!meta)return;unitLoading.value=true;try{const row=(await getSupplySource('unit',id,{audit_only:false})).data;if(!current(t)||u!==unitEpoch||!creating.value)return;if(!await verifySupplySourceWrapper(row,{kind:'unit',itemKind:localKind.value,itemId:localId.value})||!row.eligible||row.content_hash!==meta.content_hash||row.governance_hash!==meta.governance_hash)throw new Error('所选单位完整原件已变化');if(!current(t)||u!==unitEpoch||!creating.value)return;selectedUnit.value=clone(row);form.value={...form.value,unit_definition_id:id,expected_unit_content_hash:row.content_hash,expected_unit_governance_hash:row.governance_hash};}catch(e){if(current(t)&&u===unitEpoch&&creating.value)unavailable(e.message);}finally{if(current(t)&&u===unitEpoch)unitLoading.value=false;}}
async function save(){if(!validForm.value||saving.value||unitLoading.value)return;const t=epoch,body=clone(form.value),kind=recordKind.value,submitted=supportCanonical(body);saving.value=true;try{const row=(await createSupplySource(kind,body)).data;if(!current(t)||!creating.value)return;if(!await verifySupplySourceWrapper(row,{kind,itemKind:localKind.value,itemId:localId.value})||row.status!=='draft'||row.revision!==1||!samePayload(row.payload,body.payload)||row.unit_definition_id!==(kind==='unit'?row.source_record_id:body.unit_definition_id)||kind==='daily'&&((row.parent_binding.unit_definition?.content_hash??null)!==body.expected_unit_content_hash||(row.parent_binding.unit_definition?.governance_hash??null)!==body.expected_unit_governance_hash))throw new Error('登记回执与本次明确提交的完整原件不一致');if(!current(t)||!creating.value||supportCanonical(form.value)!==submitted)return;creating.value=false;form.value=null;detail.value=clone(row);basis.value='';showOriginal.value=false;emit('source-changed',row);await loadList(t);}catch(e){if(current(t))unavailable(e.message||'本次登记未得到可核对回执，请重新读取');}finally{if(current(t))saving.value=false;}}
const samePayload=(a,b)=>supportCanonical(a)===supportCanonical(b);
async function govern(action){const original=detail.value;if(!original||saving.value||!supplySourceBasis(basis.value,action==='revoke'?1000:4000))return;const t=epoch,d=detailEpoch,body={expected_revision:original.revision,expected_content_hash:original.content_hash,basis_note:basis.value};if(action!=='revoke')body.decision=action;saving.value=true;try{const row=(await (action==='revoke'?revokeSupplySource(original.record_kind,original.source_record_id,body):reviewSupplySource(original.record_kind,original.source_record_id,body))).data;if(!current(t)||d!==detailEpoch)return;if(!await verifySupplySourceTransition(row,original,action,body)||props.governance&&!row.audit_only)throw new Error('治理回执与原ID、完整原文、CAS或本次依据不一致');if(!current(t)||d!==detailEpoch)return;detail.value=clone(row);basis.value='';showOriginal.value=false;emit('source-changed',row);await loadList(t);}catch(e){if(current(t)&&d===detailEpoch)unavailable(e.message||'当前原件无法治理');}finally{if(current(t))saving.value=false;}}
watch(()=>[props.itemKind,props.itemId],([kind,id])=>{localKind.value=kind;localId.value=id;});
watch(scope,()=>{clear(initialized);initialized=true;page.value=catalogPage.value=1;if(current(epoch))boot();},{immediate:true,flush:'sync'});
