</script>

<style scoped>
.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:12px 0}.toolbar .el-select{min-width:220px}.toolbar .el-input{max-width:260px}p{line-height:1.6;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:430px;overflow:auto;background:#f5f7fa;padding:12px}
